mapper.select:
SELECT pa.asset_id
FROM `plan_asset` pa
         JOIN `asset` a ON a.id = pa.asset_id
WHERE pa.user_id = #{userId}
  AND pa.plan_id = #{planId}
ORDER BY a.code

SELECT pa.asset_id, pa.plan_id, sp.name AS plan_name
FROM `plan_asset` pa
         JOIN `saving_plans` sp ON sp.id = pa.plan_id
WHERE pa.user_id = #{userId}
  AND pa.asset_id = #{assetId}
LIMIT 1

mapper.delete:
DELETE
FROM `plan_asset`
WHERE user_id = #{userId}
  AND plan_id = #{planId}
  AND asset_id = #{assetId}
